fn total_weight(keys: [str]) -> int:
    var weights = parallel([lambda k: weight(k) for k in keys])
    return sum(weights)

fn largest_price(keys: [str]) -> str:
    var tasks = [lambda: (key, price(key)) for key in keys]
    var results = parallel(tasks)
    var max_price = 0
    var max_key = ""
    for key, price in results:
        if price > max_price:
            max_price = price
            max_key = key
    return max_key

fn largest_stock(keys: [str]) -> str:
    var tasks = [lambda: (key, stock(key)) for key in keys]
    var results = parallel(tasks)
    var max_stock = -1
    var max_key = ""
    for key, stock in results:
        if stock > max_stock:
            max_stock = stock
            max_key = key
    return max_key

fn largest_score(keys: [str]) -> str:
    var scores = parallel([lambda k: (score(k), k) for k in keys])
    var max_score = max(scores)[0]
    for (s, k) in scores:
        if s == max_score:
            return k

fn largest_weight(keys: [str]) -> str:
    var weights = parallel([lambda k: (weight(k), k) for k in keys])
    var max_weight = max(weights)[0]
    for w, k in weights:
        if w == max_weight:
            return k

fn largest_delay(keys: [str]) -> str:
    var tasks = [delay(key) for key in keys]
    var results = parallel(tasks)
    var max_delay = max(results)
    for key, delay in zip(keys, results):
        if delay == max_delay:
            return key

